            RequestValidateCheck(checkRequest, res =>
            {
                singleValidateCheckResult.bIsSuccess = res.callbackResult == IlcaNetServerCallbackResult.Success;
                singleValidateCheckResult.validateResult = res.validateResult;
                NetworkHelper.EmitNetworkLog(string.Format("RequestValidateGMS : [{0}] - [{1}]", singleValidateCheckResult.bIsSuccess, singleValidateCheckResult.validateResult));
                if (singleValidateCheckResult.validateResult == ValidateResultID.SignatureError || singleValidateCheckResult.validateResult == ValidateResultID.ProcessError)
                {
                    ShowApplicationErrorDialog(ErrorCodeID.ErrorValidateServer, appletResult =>
                    {
                        onFinished?.Invoke(singleValidateCheckResult);
                    });
                }
                else
                {
                    onFinished?.Invoke(singleValidateCheckResult);
                }
            });
        }
		private bool CheckValidateTargetData(params global::Pml.PokePara.CoreParam[] coreParamArray) {
            if (coreParamArray == null)
                return false;

            for (int i = 0; i < coreParamArray.Length; i++)
            {
                if (coreParamArray[i] == null)
                {
                    // Stripped log (@01de9600): only the format call survives.
                    string.Format("Validate Data Error : Traget data[{0}] is null", i);
                    return false;
                }
            }

            return true;
        }
		private void SettingCheckRequestData(params global::Pml.PokePara.CoreParam[] coreParamArray) {
            // Stripped log (@01de96cc): only the format call survives.
            string.Format("Request Validate DataNum :[{0}]", coreParamArray.Length);
            checkRequest.ROMVersion = (ushort)(PlayerWork.playerData.mystatus.rom_code != 0 ? CassetVersion.DPR_S : CassetVersion.DPR_B);
            checkRequest.GameMode = NetworkConstants.VALIDATE_GAME_MODE;
            checkRequest.DataNum = (ushort)coreParamArray.Length;
            checkRequest.Data = new byte[checkRequest.DataNum * CoreParam.DATASIZE];
            int offset = 0;
            for (int i = 0; i < coreParamArray.Length; i++)
            {
                if (coreParamArray[i] == null)
                    continue;

                CoreParam coreParam = new CoreParam();
                coreParam.CopyFrom(coreParamArray[i]);
                if (coreParam.GetMemories(Memories.EGG_TAKEN_PLACE) == 0xffff)
                {
                    // Stripped log (@01de9860): only the format call survives.
                    string.Format("[{0}] is [{1}]", Memories.EGG_TAKEN_PLACE, 0xffffu);
                    coreParam.SetMemories(Memories.EGG_TAKEN_PLACE, 0);
                }

                if (coreParam.IsEgg(EggCheckType.ONLY_LEGAL_EGG) && coreParam.GetMemories(Memories.FIRST_CONTACT_PLACE) == 0xffff)
                {
                    // Stripped log (@01de98f4): only the format call survives.
                    string.Format("[{0}] is [{1}]", Memories.FIRST_CONTACT_PLACE, 0xffffu);
                    coreParam.SetMemories(Memories.FIRST_CONTACT_PLACE, 0);
                }

                Array.Copy(coreParam.GetCoreData(), 0, checkRequest.Data, offset, CoreParam.DATASIZE);
                offset += CoreParam.DATASIZE;
            }
        }
		private void RequestValidateCheck(global::INL1.IlcaNetServerValidate.CheckRequest cReq, global::System.Action<global::Dpr.NetworkUtils.RequestValidateResult> onCompleteCheck) {
            validateResult.Reset();
            if (!IlcaNetServerValidate.CheckRequestAutoAsync(this, cReq, (isSuccess, eve, result, responseCode, responseStr) =>
            {
                if (eve != IlcaNetServerCallbackEventType.CheckValidateRequestAsync)
                {
                    validateResult.validateResult = ValidateResultID.ProcessError;
                    EmitSessionErrorLog(SessionErrorType.Validate_CallDifferentRequest);
                }
                else if (!isSuccess)
                {
                    validateResult.validateResult = ValidateResultID.ProcessError;
                    EmitSessionErrorLog(SessionErrorType.Validate_RequestResultFailed);
                }
                else
                {
                    validateResult.callbackResult = result;
                    CheckUpdateValidatePublicKey();
                    if (result != IlcaNetServerCallbackResult.Success)
                    {
                        validateResult.validateResult = CheckIllegalResultData();
                        EmitSessionErrorLog(SessionErrorType.Validate_FindIllegalData);
                    }
                    else
                    {
                        HasCheckResponse();
                    }
                }

                onCompleteCheck?.Invoke(validateResult);
            }))
            {
                validateResult.validateResult = ValidateResultID.ProcessError;
                EmitSessionErrorLog(SessionErrorType.Failed_CheckRequestAutoAsync);
                onCompleteCheck?.Invoke(validateResult);
            }
        }
		private void CheckUpdateValidatePublicKey() {
            IlcaNetServerValidate.PublicKeyResponse publicKeyResponse = new IlcaNetServerValidate.PublicKeyResponse();
            if (!IlcaNetServerValidate.PublicKeyResponseGet(ref publicKeyResponse))
            {
                EmitSessionErrorLog(SessionErrorType.Validate_FailedGetPublicKey);
                return;
            }

            if (PlayerWork.networkData.publicKeyversion != publicKeyResponse.PublicKeyVersion)
            {
                PlayerWork.networkData.publicKeyversion = publicKeyResponse.PublicKeyVersion;
                PlayerWork.networkData.publicKeyBASE64 = publicKeyResponse.PublicKeyValueBASE64;
            }
        }
		private global::Dpr.NetworkUtils.ValidateResultID CheckIllegalResultData() {
            if (!HasCheckResponse())
            {
                EmitSessionErrorLog(SessionErrorType.Validate_FailedGetIllegalData);
                return ValidateResultID.ProcessError;
            }

            NetworkHelper.EmitValidateError(checkResponse);
            for (int i = 0; i < checkResponse.DataResult.Length; i++)
            {
                if (checkResponse.DataResult[i] != 0)
                    return ValidateResultID.InvalidData;
            }

            return ValidateResultID.SignatureError;
        }
		private bool HasCheckResponse() {
            return checkResponse != null && IlcaNetServerValidate.CheckResponseGet(ref checkResponse);
        }
		public void DoGMSTrade(int dataPointNo, global::System.Action<global::Dpr.NetworkUtils.GMSTradeResult> onComplete) {
            gmsTradeResult.Clear();
            if (!IlcaNetServerDataStoreService.GMStationTrade(this, dataPointNo, checkRequest, checkResponse.Signature, (isSuccess, result, playerCoreDataDelete) =>
            {
                gmsTradeResult.bIsSuccess = isSuccess;
                gmsTradeResult.bNeedDelete = playerCoreDataDelete;
                if (isSuccess)
                {
                    gmsTradeResult.coreDatas = new byte[CoreParam.DATASIZE];
                    ushort point = 0;
                    IlcaNetServerDataStoreService.GMStationTradeCoreDataInstanceGet(gmsTradeResult.coreDatas, ref point);
                    gmsTradeResult.pointNo = point;
                }
                else
                {
                    gmsTradeResult.coreDatas = null;
                    switch (result)
                    {
                        case IlcaNetServerDataStoreService.GMstationTradeStatusEnum.ERROR_CALL:
                            gmsTradeResult.tradeResult = GMstationTradeStatusEnum.ERROR_CALL;
                            break;
                        case IlcaNetServerDataStoreService.GMstationTradeStatusEnum.ERROR_SERVER:
                            gmsTradeResult.tradeResult = GMstationTradeStatusEnum.ERROR_SERVER;
                            break;
                        case IlcaNetServerDataStoreService.GMstationTradeStatusEnum.ERROR_SIGNATURE:
                            gmsTradeResult.tradeResult = GMstationTradeStatusEnum.ERROR_SIGNATURE;
                            break;
                        case IlcaNetServerDataStoreService.GMstationTradeStatusEnum.ERROR_EMPTY:
                            gmsTradeResult.tradeResult = GMstationTradeStatusEnum.ERROR_EMPTY;
                            break;
                    }
                }

                onComplete?.Invoke(gmsTradeResult);
            }, false))
            {
                EmitSessionErrorLog(SessionErrorType.Failed_CallGMStationTrade);
                gmsTradeResult.bIsSuccess = false;
                gmsTradeResult.bNeedDelete = false;
                gmsTradeResult.pointNo = -1;
                gmsTradeResult.coreDatas = null;
                onComplete?.Invoke(gmsTradeResult);
            }
        }
