		public void OnUpdate(float deltaTime) {
            if (sessionConnector.IsRunning)
            {
                sessionConnector.OnUpdate();
                CheckReceivePacket();
            }
        }
		public void CheckReceivePacket() {
            CheckReceivePacketImpl(TransportType.Station, -1, onReceivePacket, onReceivePacketEx);
            for (int i = 0; i < IlcaNetBase.MaxGamers; i++)
                CheckReceivePacketImpl(TransportType.Gamer1, i, null, onReceivePacketEx);
            for (int i = 0; i < IlcaNetBase.MaxGamers; i++)
                CheckReceivePacketImpl(TransportType.Gamer2, i, null, onReceivePacketEx);
        }
		private void CheckReceivePacketImpl(global::Dpr.NetworkUtils.TransportType transportType, int receiveStationIndex, global::Dpr.NetworkUtils.NetworkManager.ReceivePacketCallback _onReceivePacket, global::Dpr.NetworkUtils.NetworkManager.ReceivePacketExCallback _onReceivePacketEx) {
            IlcaNetTransport transport = sessionConnector.GetTransport(transportType, receiveStationIndex);
            if (transport == null)
                return;

            IlcaNetGamer gamer = transport as IlcaNetGamer;
            if (gamer != null && (!gamer.IsActive() || gamer.IsHomeGamer()))
                return;

            while (transport.Recv(ref packetReader) > 0)
            {
                _onReceivePacket?.Invoke(packetReader);
                _onReceivePacketEx?.Invoke(packetReader, transportType, receiveStationIndex);
            }
        }
