		public void SetupMasterData(global::XLSXContent.NetworkData networkData) {
            foreach (var logInfo in networkData.ErrorLogInfo)
            {
                if (!sessionErrorLogTable.ContainsKey((int)logInfo.errorID))
                    sessionErrorLogTable.Add((int)logInfo.errorID, logInfo.errorLog);
            }

            foreach (var dialogInfo in networkData.ErrorDialogInfo)
            {
                if (!networkErrorDialogTable.ContainsKey((int)dialogInfo.errorCode))
                    networkErrorDialogTable.Add((int)dialogInfo.errorCode, dialogInfo);
            }
        }
