		private void OpenErrorDialog(uint errorCode, global::System.Action<global::Dpr.NetworkUtils.ErrorAppletResult> onCloseWindow) {
            // Stripped logs (@01deafb4, @01deaff0): only the format calls survive.
            string.Format("Open Application Error Dialog - ErrorCode [{0}]", errorCode);
            if (systemErrorDialogOpenCount > 0)
                string.Format("Open Application Error Dialog -  mulitple dialog. count=[{0}]", systemErrorDialogOpenCount);

            if (!networkErrorDialogTable.ContainsKey((int)errorCode))
            {
                EmitSessionErrorLog(SessionErrorType.Error_NotFoundErrorCode);
                appletResult.errorLevel = ErrorLevelID.None;
                onCloseWindow?.Invoke(appletResult);
                return;
            }

            NetworkData.SheetErrorDialogInfo dialogData = networkErrorDialogTable[(int)errorCode];
            switch ((ErrorViewType)dialogData.viewType)
            {
                case ErrorViewType.Applet:
                {
                    appletResult.errorLevel = (ErrorLevelID)dialogData.errorLevel;
                    string langCode = NetworkConstants.LANG_CODE_TABLE[(int)MessageManager.Instance.UserLanguageID];
                    string dialogMessage = GetErrorMessage(dialogData.useTitleMsbtName, dialogData.useTitleLabelName);
                    string screenMessage = GetErrorMessage(dialogData.useDetailMsbtName, dialogData.useDetailLabelName);
                    IlcaNetBase.ErrorViewerOriginal(errorCode, dialogMessage, screenMessage, langCode);
                    onCloseWindow?.Invoke(appletResult);
                    return;
                }
                case ErrorViewType.SystemWindow:
                {
                    appletResult.errorLevel = (ErrorLevelID)dialogData.errorLevel;
                    Dpr.UI.DialogWindow dialogWindow = Dpr.UI.UIManager.Instance.CreateUIWindow<Dpr.UI.DialogWindow>(UIWindowID.DIALOG);
                    if (dialogWindow != null)
                    {
                        systemErrorDialogOpenCount++;
                        systemErrorDialogCode = (ErrorCodeID)errorCode;
                        dialogWindow.onClosed = window =>
                        {
                            onCloseWindow?.Invoke(appletResult);
                            systemErrorDialogOpenCount = Mathf.Max(systemErrorDialogOpenCount - 1, 0);
                            if (systemErrorDialogOpenCount == 0)
                                systemErrorDialogCode = ErrorCodeID.NUM;
                        };
                        dialogWindow.Open(text =>
                        {
                            text.text = GetErrorMessage(dialogData.useTitleMsbtName, dialogData.useTitleLabelName);
                        }, NetworkConstants.ADD_ERROR_DIALOG_SORT, Dpr.UI.UIWindow.WINDOWID_FIELD, true);
                        return;
                    }
                    break;
                }
                case ErrorViewType.FatalError:
                {
                    appletResult.errorLevel = (ErrorLevelID)dialogData.errorLevel;
                    Dpr.UI.FatalErrorDialogWindow fatalWindow = Dpr.UI.UIManager.Instance.CreateUIWindow<Dpr.UI.FatalErrorDialogWindow>(UIWindowID.FATAL_ERROR_DIALOG);
                    if (fatalWindow != null)
                    {
                        systemErrorDialogOpenCount++;
                        systemErrorDialogCode = (ErrorCodeID)errorCode;
                        fatalWindow.onClosed = window =>
                        {
                            onCloseWindow?.Invoke(appletResult);
                            systemErrorDialogOpenCount = Mathf.Max(systemErrorDialogOpenCount - 1, 0);
                            if (systemErrorDialogOpenCount == 0)
                                systemErrorDialogCode = ErrorCodeID.NUM;
                        };
                        fatalWindow.Open(text =>
                        {
                            text.text = GetErrorMessage(dialogData.useTitleMsbtName, dialogData.useTitleLabelName);
                        });
                        return;
                    }
                    break;
                }
            }

            // Stripped log (@01deb490): only the format call survives.
            string.Format("Invalid ErrorViewType : {0}", (ErrorViewType)dialogData.viewType);
            onCloseWindow?.Invoke(appletResult);
        }
		private string GetErrorMessage(string msbtName, string labelName) {
            if (string.IsNullOrEmpty(msbtName) || string.IsNullOrEmpty(labelName))
                return string.Empty;

            return MessageManager.Instance.GetMsgFile(msbtName)?.GetNameStr(labelName);
        }
		private void EmitSessionErrorLog(global::Dpr.NetworkUtils.SessionErrorType errorType) {
            // The log call itself is stripped from the shipped build; only the message lookup remains (@01de9f50).
            string errorLog = null;
            if (errorType != SessionErrorType.None)
            {
                if (!sessionErrorLogTable.TryGetValue((int)errorType, out errorLog))
                    errorLog = string.Format("Unknown Error: key[{0}]", (int)errorType);
            }
        }
		private void OnResume(int value) {
            if (IsConnect)
            {
                sessionConnector.SetCallOnFinishedSessionFlag(false);
                FinishSession();
                SessionEventData sessionEvent = new SessionEventData();
                sessionEvent.stationIndex = MyStationIndex;
                sessionEvent.eventType = SessionEventType.ResumeGame;
                onSessionEvent?.Invoke(sessionEvent);
            }
        }
